    X = Integer(_sage_const_2  ** int(beta2*n))
    Y = Integer(_sage_const_2  ** int(n-alpha*n-gamma*n-beta1*n))
    Z = Integer(_sage_const_2  ** int(alpha*n))
    W = Integer(_sage_const_2  ** int(n-alpha*n))
    M = Integer(_sage_const_2  ** int(beta2*n-beta1*n))
